pe="submit">Lưu</button></form><?php endif; ?><a class="action-button" href="/admin/orders/<?= (int)$order['id'] ?>">Chi tiết</a></td></tr><?php endforeach; ?></tbody></table></div><button type="button" class="button show-more-button" data-show-more-target="admin-orders-list" hidden>Xem thêm đơn hàng</button><?php endif; ?>
